// Writes `src/cloud/build-config.ts` from the build's environment: the
// Supabase project and the Sentry DSNs this build talks to. `build`,
// `typecheck` and `test` run it before `tsc`, so a fresh clone with none of
// the variables set still builds; an unset or blank variable is left out of
// the file, and `src/cloud/config.ts`, its only reader, treats it as absent.
//
// The generated file is gitignored. This script prints the names of the
// variables it found, never a value: a value can be a key.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const VARIABLES = {
  supabaseUrl: 'SENSEI_TOP_SUPABASE_URL',
  supabaseAnonKey: 'SENSEI_TOP_SUPABASE_ANON_KEY',
  sentryDsnDesktop: 'SENSEI_TOP_SENTRY_DSN_DESKTOP',
  sentryDsnLocalApi: 'SENSEI_TOP_SENTRY_DSN_LOCAL_API',
};

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'cloud', 'build-config.ts');

// The Supabase URL is the project's bare address: the auth and data paths
// are added to it. A copied API URL (`…/rest/v1/`) still parses, so the
// build would ship an app whose sign-in reaches the data API and fails. It
// is refused before anything is written; the message names the variable
// and the part that is wrong, never the value.
function supabaseUrlProblem(value) {
  let url;
  try {
    url = new URL(value);
  } catch {
    return 'is not a URL';
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return 'is not an http(s) address';
  if (url.pathname !== '/') return 'has a path; give the bare project address, e.g. https://<ref>.supabase.co';
  if (url.search !== '' || url.hash !== '') return 'has a query or a fragment';
  return null;
}

const fields = [];
const found = [];
for (const [field, variable] of Object.entries(VARIABLES)) {
  const value = (process.env[variable] ?? '').trim();
  if (value === '') continue;
  if (field === 'supabaseUrl') {
    const problem = supabaseUrlProblem(value);
    if (problem) {
      console.error(`build-config: ${variable} ${problem}`);
      process.exit(1);
    }
  }
  fields.push(`  ${field}: ${JSON.stringify(value)},`);
  found.push(variable);
}

const text = [
  '// Generated by scripts/build-config.mjs from the build environment; gitignored.',
  '// Read only through ./config.ts.',
  '',
  'export const BUILD_CONFIG: {',
  ...Object.keys(VARIABLES).map((field) => `  readonly ${field}?: string;`),
  '} = {',
  ...fields,
  '};',
  '',
].join('\n');

let previous = null;
try {
  previous = readFileSync(out, 'utf8');
} catch {
  // not written yet
}
// An unchanged file is left alone, so tsc and vitest see no new mtime.
if (previous !== text) {
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, text);
}
console.log(`build-config: ${found.length > 0 ? found.join(', ') : 'no cloud variables'} set`);
